export const leadTrial = (f: ScreenFeature) => f.trials.find((t) => t.h === f.lead_h) ?? f.trials[0];

/** Trial at horizon `h` ("lead" = the horizon the verdict is about); falls back to the lead trial. */
export function trialAt(f: ScreenFeature, h: "lead" | number): ScreenTrial {
	if (h === "lead") return leadTrial(f);
	return f.trials.find((t) => t.h === h) ?? leadTrial(f);
}

/** Round axis ticks inside [min, max], aligned to multiples of a nice step (1/2/5 × 10^k). */
export function niceTicks(min: number, max: number): number[] {
	const lo = Math.min(min, max);
	const hi = Math.max(min, max);
	if (!Number.isFinite(lo) || !Number.isFinite(hi)) return [0];
	const range = hi - lo;
	if (range <= 0) return [lo];
	const raw = range / 5;
	const pow = 10 ** Math.floor(Math.log10(raw));
	const norm = raw / pow;
	const step = norm < 1.5 ? pow : norm < 3 ? 2 * pow : norm < 7 ? 5 * pow : 10 * pow;
	const decimals = Math.max(0, -Math.floor(Math.log10(step)));
	const clean = (v: number) => Number(v.toFixed(decimals));
	const ticks: number[] = [];
	for (let v = Math.ceil(lo / step) * step; v <= hi + step * 1e-9; v += step) ticks.push(clean(v));
	return ticks;
}

/** UTC date as `YYYY.MM.DD` (dots, never `-MM`/`-DD`, so a day is not read as a month tick). */
export function dateLabel(ts: number): string {
	const d = new Date(ts);
	const y = d.getUTCFullYear();
	const m = String(d.getUTCMonth() + 1).padStart(2, "0");
	const day = String(d.getUTCDate()).padStart(2, "0");
	return `${y}.${m}.${day}`;
}

export interface CurveView {
	t: number[];
	rule: number[];
	hold: number[];
	ticks: number[];
	labels: string[];
}

/**
 * Cumulative-profit curve of a trial in percent: fraction sums ×100, with a missing point
 * carried over from the previous value (a leading missing point carries 0).
 */
export function curveView(trial: ScreenTrial | undefined | null): CurveView | null {
	const curve = trial?.curve;
	if (!curve || !curve.t || curve.t.length < 2) return null;
	const toPercent = (series: (number | null)[]) => {
		let last = 0;
		return series.map((v) => {
			if (v == null || !Number.isFinite(v)) return last;
			last = v * 100;
			return last;
		});
	};
	const rule = toPercent(curve.rule ?? []);
	const hold = toPercent(curve.hold ?? []);
	const values = [...rule, ...hold];
	return {
		t: curve.t,
		rule,
		hold,
		ticks: niceTicks(Math.min(...values), Math.max(...values)),
		labels: curve.t.map(dateLabel),
	};
}

export interface ScreenRuleTile {
	id: string;
	group: "entry" | "fill" | "exit";
	name: string;
	label: string;
	tip: string;
}

/** The screen's trade rule as tiles: indicator, direction, (down-regime gate), fill cost, hold. */
export function screenRule(doc: ScreenDoc, f: ScreenFeature, trial: ScreenTrial): ScreenRuleTile[] {
	const fixed = doc.fixed_sign != null;
	const sign = fixed ? doc.fixed_sign! : trial.train_sign;
	const long = sign >= 0;
	const signs = new Set((trial.folds ?? []).map((fold) => Math.sign(fold.train_sign)));
	const changed = !fixed && signs.size > 1;
	const directionLabel = changed ? "부호 바뀜" : fixed || long ? "순방향" : "역추세";
	const directionTip = fixed
		? `방향 부호가 ${sign > 0 ? "+1" : "−1"}로 고정된 규칙이라, 기준(0) 위면 ${long ? "롱" : "숏"}, 아래면 ${long ? "숏" : "롱"}이다.`
		: changed
			? "학습 연도마다 부호가 달라 기준 위면의 방향이 해마다 바뀐다."
			: long
				? "학습 부호가 양수라 기준 위면 롱, 아래면 숏이다."
				: "학습 부호가 음수라 기준 위면 숏, 아래면 롱인 역추세 규칙이다.";
	const bp = doc.cost_per_side * 1e4;
	const bpLabel = Number.isInteger(bp) ? String(bp) : String(Math.round(bp * 100) / 100);
	const tiles: ScreenRuleTile[] = [
		{
			id: "indicator",
			group: "entry",
			name: featureName(f),
			label: f.tradeable === false ? "참고 지표" : "거래 가능",
			tip:
				f.tradeable === false
					? "그의 체결은 실시간으로 공개되지 않아 따라갈 수 없어, 참고 지표로만 본다."
					: `원천 지표 ${f.feature}. 이 값이 기준을 넘으면 진입 신호가 된다.`,
		},
		{
			id: "direction",
			group: "entry",
			name: `기준 위면 ${long ? "롱" : "숏"}`,
			label: directionLabel,
			tip: directionTip,
		},
	];
	if (doc.regime === "down") {
		tiles.push({
			id: "regime",
			group: "entry",
			name: "하락 레짐만",
			label: "레짐 게이트",
			tip: "종가가 200일 평균 아래인 날만 점수를 매기고 매매한다.",
		});
	}
	tiles.push(
		{
			id: "fill",
			group: "fill",
			name: `편도 ${bpLabel}bp`,
			label: "체결 비용",
			tip: `한 번 사고팔 때마다 편도 ${bpLabel}bp의 비용(보수적 2배)과 실제 펀딩을 뺀다.`,
		},
		{
			id: "hold",
			group: "exit",
			name: `${trial.h}${doc.unit} 보유`,
			label: "보유 기간",
			tip: `진입 후 ${trial.h}${doc.unit} 동안 들고 시계가 끝나면 청산한다.`,
		},
	);
	return tiles;
}

